fn write_pkg(root: &std::path::Path, rel: &str, eco: Ecosystem, name: &str) {
    std::fs::create_dir_all(root.join(rel)).unwrap();
    match eco {
        Ecosystem::Cargo => std::fs::write(root.join(rel).join("Cargo.toml"), format!("[package]\nname = \"{name}\"\nversion = \"0.1.0\"\nedition = \"2021\"\n")).unwrap(),
        Ecosystem::Npm => std::fs::write(root.join(rel).join("package.json"), format!(r#"{{"name":"{name}","version":"0.1.0"}}"#)).unwrap(),
        Ecosystem::Pypi => std::fs::write(root.join(rel).join("pyproject.toml"), format!("[project]\nname = \"{name}\"\nversion = \"0.1.0\"\n")).unwrap(),
        _ => unreachable!(),
    }
}

